    }

    ProcessStartInfo startInfo = new ProcessStartInfo
    {
        FileName = fileName,
        Arguments = arguments,
        Verb = "runas",
        UseShellExecute = false,
        CreateNoWindow = true
    };

    try
    {
        using (Process process = Process.Start(startInfo))
        {
            process.WaitForExit();
            return true;
        }
    }
    catch (Win32Exception ex)
    {
        _log.Error("Process Start Exception", ex);
        return false;
    }
    catch (Exception ex)
    {
        _log.Error("Unexpected Exception", ex);
        return false;
    }
}

private bool IsValidFileName(string fileName)
{
    // Implement validation logic for file name
    return !string.IsNullOrEmpty(fileName) && !fileName.Contains(";");
}

private bool IsValidArguments(string arguments)
{
    // Implement validation logic for arguments
    return !string.IsNullOrEmpty(arguments) && !arguments.Contains(";");
}"}
